def get_adjacent_neighbors(grid, r, c):
    rows, cols = len(grid), len(grid[0])
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == grid[r][c]:
            yield (nr, nc)

def bfs_component(grid, start_r, start_c):
    rows, cols = len(grid), len(grid[0])
    component = [(start_r, start_c)]
    queue = [(start_r, start_c)]
    visited = set([(start_r, start_c)])
    idx = 0
    while idx < len(queue):
        r, c = queue[idx]
        idx += 1
        for nr, nc in get_adjacent_neighbors(grid, r, c):
            if (nr, nc) not in visited:
                visited.add((nr, nc))
                component.append((nr, nc))
                queue.append((nr, nc))
    return sorted(component)

